#include <limits.h>

// Assuming gfx::Rect is defined as follows:
typedef struct {
    int x;
    int y;
    int width;
    int height;
} gfx_Rect;

gfx_Rect GetBoundsForClientView(const gfx_Rect* client_bounds) {
    // Placeholder implementation for GetBoundsForClientView
    // This is a simplified version that returns the client bounds directly
    // In a real implementation, this would adjust for frameless/fullscreen states
    return *client_bounds;
}

gfx_Rect GetWindowBoundsForClientBounds(const gfx_Rect* client_bounds) {
    // Constants for caption height and close button width
    const int kCaptionHeight = 30;
    const int kCloseButtonWidth = 20;

    // Calculate window bounds by adding caption height and close button width
    // to the client bounds
    gfx_Rect window_bounds = {0};

    // Validate input to ensure no overflow occurs
    if (client_bounds->x < 0 || client_bounds->y < 0 ||
        client_bounds->width <= 0 || client_bounds->height <= 0) {
        // Return an invalid rect if input is invalid
        window_bounds.x = INT_MIN;
        window_bounds.y = INT_MIN;
        window_bounds.width = 0;
        window_bounds.height = 0;
        return window_bounds;
    }

    // Check for overflow when adding caption height and close button width
    if (client_bounds->height > INT_MAX - kCaptionHeight ||
        client_bounds->width > INT_MAX - kCloseButtonWidth) {
        // Return an invalid rect if overflow would occur
        window_bounds.x = INT_MIN;
        window_bounds.y = INT_MIN;
        window_bounds.width = 0;
        window_bounds.height = 0;
        return window_bounds;
    }

    window_bounds.x = client_bounds->x;
    window_bounds.y = client_bounds->y - kCaptionHeight;
    window_bounds.width = client_bounds->width + kCloseButtonWidth;
    window_bounds.height = client_bounds->height + kCaptionHeight;

    return window_bounds;
}
